CREATE TABLE `workpacks` (
  `WORKPACK_ID` int NOT NULL AUTO_INCREMENT,
  `LAST_UPDATED_DATE` datetime DEFAULT NULL,
  `LAST_UPDATED_USER` int DEFAULT NULL,
  `MANAGEMENT_OF_CHANGE_ID` int DEFAULT NULL,
  `INSTALLATION_ID` int NOT NULL,
  `WORKPACK_TYPE_ID` int NOT NULL,
  `WORKPACK_YEAR` int NOT NULL,
  `CODE` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `TITLE` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `WORKPACK_COST_CODE_ID` int DEFAULT NULL,
  `DESCRIPTION` mediumtext COLLATE utf8mb4_unicode_ci,
  `CMMS_REF` varchar(250) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `CMMS_URL` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `EXTERNAL_REF` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `GENERATION_TYPE` int DEFAULT NULL,
  `PROCEDURE_REF` int DEFAULT NULL,
  `PLANNED_DATE_START` datetime DEFAULT NULL,
  `PLANNED_DATE_FINISH` datetime DEFAULT NULL,
  `REVISED_DATE_START` datetime DEFAULT NULL,
  `REVISED_DATE_FINISH` datetime DEFAULT NULL,
  `ACTUAL_DATE_START` datetime DEFAULT NULL,
  `ACTUAL_DATE_FINISH` datetime DEFAULT NULL,
  `ELEMENT_ID` int NOT NULL,
  `ROLE_ID` int DEFAULT NULL,
  `WORKPACK_STATUS_ID` int NOT NULL,
  PRIMARY KEY (`WORKPACK_ID`),
  UNIQUE KEY `WORKPACK_ID` (`WORKPACK_ID`),
  UNIQUE KEY `WORKPACKS_ELEMENT_ID_INSTALLATION_ID_WORKPACK_YEAR_CODE_UNIQUE` (`ELEMENT_ID`,`INSTALLATION_ID`,`WORKPACK_YEAR`,`CODE`),
  KEY `WORKPACKS_INSTALLATION_ID_FK` (`INSTALLATION_ID`),
  KEY `WORKPACKS_WORKPACK_TYPE_ID_FK` (`WORKPACK_TYPE_ID`),
  KEY `WORKPACKS_WORKPACK_COST_CODE_ID_FK` (`WORKPACK_COST_CODE_ID`),
  KEY `WORKPACKS_PROCEDURE_REF_FK` (`PROCEDURE_REF`),
  KEY `WORKPACKS_ROLE_ID_FK` (`ROLE_ID`),
  KEY `WORKPACKS_WORKPACK_STATUS_ID_FK` (`WORKPACK_STATUS_ID`),
  KEY `WORKPACKS_LAST_UPDATED_USER_FK` (`LAST_UPDATED_USER`),
  KEY `WORKPACKS_CMMS_REF` (`CMMS_REF`),
  CONSTRAINT `WORKPACKS_ELEMENT_ID_FK` FOREIGN KEY (`ELEMENT_ID`) REFERENCES `elements` (`ELEMENT_ID`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `WORKPACKS_INSTALLATION_ID_FK` FOREIGN KEY (`INSTALLATION_ID`) REFERENCES `components` (`COMPONENT_ID`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `WORKPACKS_LAST_UPDATED_USER_FK` FOREIGN KEY (`LAST_UPDATED_USER`) REFERENCES `users` (`USER_ID`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `WORKPACKS_PROCEDURE_REF_FK` FOREIGN KEY (`PROCEDURE_REF`) REFERENCES `property_values` (`PROPERTY_VALUE_ID`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `WORKPACKS_ROLE_ID_FK` FOREIGN KEY (`ROLE_ID`) REFERENCES `roles` (`ROLE_ID`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `WORKPACKS_WORKPACK_COST_CODE_ID_FK` FOREIGN KEY (`WORKPACK_COST_CODE_ID`) REFERENCES `workpack_cost_codes` (`WORKPACK_COST_CODE_ID`) ON DELETE RESTRICT ON UPDATE RESTRICT,
