  CONSTRAINT `WORKPACKS_WORKPACK_TYPE_ID_FK` FOREIGN KEY (`WORKPACK_TYPE_ID`) REFERENCES `property_values` (`PROPERTY_VALUE_ID`) ON DELETE RESTRICT ON UPDATE RESTRICT
